#include "test_helpers.h"
#include "roms/generated/test_irq.h"   // auto-generated by: make -f src/build.mk roms

// ============================================================
// Tier-2 ROM test: test_irq.s assembled with real Score7 GAS.
// Exercises CR-form mfcr/mtcr/rte, the 16-byte-spaced IRQ vector for
// source 10 (vector 53), PPU status acknowledge, the controller mask
// register, and the syscall general vector.
// ============================================================

static constexpr uint32_t IRQ_COUNTER_ADDR = 0x2000;
static constexpr uint32_t SAVED_ECR_ADDR   = 0x2004;

TEST_F(ROMFixture, IRQ_GAS_ROM_VBlankAndSyscall_Passes)
{
    runROMWithVBlank(rom_test_irq, rom_test_irq_len, 200);
    EXPECT_TRUE(romPassed())
        << "ROM result: 0x" << std::hex << romResult();
    EXPECT_GE(bus.read32(IRQ_COUNTER_ADDR), 3u);
    EXPECT_EQ(bus.read32(SAVED_ECR_ADDR) & spg290::ECR_CODE_MASK, 7u);
}

// Mutation test: without a vblank source the ROM never sees its three
// interrupts, so it cannot reach the pass result.
TEST_F(ROMFixture, IRQ_GAS_ROM_DoesNotPassWithoutVBlank)
{
    runROMWithVBlank(rom_test_irq, rom_test_irq_len, 0, 20000);
    EXPECT_FALSE(romPassed());
    EXPECT_EQ(bus.read32(IRQ_COUNTER_ADDR), 0u);
}
